CREATE FUNCTION cmd_validate_house_gambling_receipt() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r rule_gambling_house_odds%ROWTYPE; dice_total integer; task cmd_actor_task_receipt%ROWTYPE;
BEGIN SELECT * INTO STRICT r FROM rule_gambling_house_odds WHERE rule_id=NEW.odds_rule_id; SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; SELECT sum(result) INTO dice_total FROM cmd_random_draw WHERE command_id=NEW.task_command_id AND draw_group='task';
 IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>(SELECT rule_id FROM rule_rule WHERE rule_code='skill.gambling') OR NEW.check_modifier<>r.check_modifier OR NEW.natural_two<>(dice_total=2) OR NEW.won<>(task.succeeded AND dice_total<>2) OR NEW.payoff_numerator IS DISTINCT FROM r.payoff_numerator OR NEW.payoff_denominator IS DISTINCT FROM r.payoff_denominator OR (r.maximum_bet_credits IS NOT NULL AND NEW.bet_credits>r.maximum_bet_credits) THEN RAISE EXCEPTION 'House gambling receipt conflicts with rules or task evidence'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cmd_house_gambling_receipt_valid BEFORE INSERT ON cmd_house_gambling_receipt FOR EACH ROW EXECUTE FUNCTION cmd_validate_house_gambling_receipt();
